      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "कितने quintal चाहिए होगी आपको?"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "Ma'am जैसे मतलब कि अगर मैं नए business से start कर रहा हूं तो मैं सोच रहा था चाय का business करना चाहता था मैं।"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "मैंने कहा अभी एक कोई छोटी opening की है दुकान की तो जैसे normal जैसे कम से कम कितना होता है पहले चाय का?"
    },
    {
      "i": 8,
      "speaker": "caller",
      "text": "इतनी लेनी पड़ती है?"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "बहुत बढ़िया।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "आप शुरुआत के लिए एक अंदाजा बता दीजिए जैसे कि एक quintal या उससे कम कितनी quantity चाहिए होगी?"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "Ma'am बीस kg मतलब अभी तो इतना तो बहुत होगा।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "चलिए अब के form के बारे में।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "जी बताइए आप कुछ कह रहे थे?"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "चलिए अब piece की बात।"
    },
    {
      "i": 16,
      "speaker": "caller",
      "text": "भाई मैं मैं ऐसे कह रहा हूं कि अगर अभी ये बीस किलो ले ले अगर वो अच्छी आती है या फिर sample भी मिल सकता है क्या ऐसे का?"
    },
    {
      "i": 17,
      "speaker": "caller",
      "text": "चाय का तो फिर उसके according भाई वही चाय मंगवा ले।"
    },
    {
      "i": 18,
      "speaker": "caller",
      "text": "भाई चार पांच प्रकार की अगर BP कौन कौन सी आती है ऐसी चाय आती है बहुत सारी।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "जी sample और variety के लिए आप seller से बात कर सकते हैं।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "बस यह बता दीजिए कि tea form में आपको leaf dust या granules में से क्या चाहिए?"
    },
    {
      "i": 21,
      "speaker": "caller",
      "text": "Ma'am मैं समझा नहीं ये क्या होता है।"
    },
    {
      "i": 22,
      "speaker": "bot",
      "text": "कोई बात नहीं मैं समझा देती हूँ।"
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "leaves यानी पत्ती वाली चाय, dust बारीक चाय और granular दानेदार चाय होती है।"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "आप क्या prefer करेंगे?"
    },
    {
      "i": 25,
      "speaker": "caller",
      "text": "हाँ जी दानेदार वाली और dust वाली दोनों चाहिएगी मेरे को।"
    },
    {
      "i": 26,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 27,
      "speaker": "bot",
      "text": "मैं देख पा रही हूं।"
    },
    {
      "i": 28,
      "speaker": "bot",
      "text": "आपको grade में OS ही चाहिए ना?"
    },
    {
      "i": 29,
      "speaker": "caller",
      "text": "Ma'am ये तो मैं नहीं समझता वो ऐसी वगैरह ऐसे तो पर मतलब पीने में अच्छी हो चाहे मतलब ठीक हो मतलब कैसे।"
    }
  ]
